#!/usr/bin/env node
import {
  AI_PROVIDER_LABEL,
  RECOMMENDED_MODELS,
  buildAiModel,
  resolveAiSelection
} from "./chunk-7XJYGZMH.js";
import {
  AI_PROVIDERS
} from "./chunk-5APUWLPI.js";
import {
  ExitCode,
  GramCLIError
} from "./chunk-IXNX2GX7.js";

// src/core/ai-args.ts
var AI_ARGS = {
  model: {
    type: "string",
    description: "Override the AI model for this run"
  },
  provider: {
    type: "string",
    description: `Override the AI provider for this run (${AI_PROVIDERS.join(" | ")})`
  },
  "pick-model": {
    type: "boolean",
    description: "Choose the provider and model interactively",
    default: false
  }
};
function parseAiOverrides(args) {
  const overrides = {};
  if (args.provider) {
    if (!AI_PROVIDERS.includes(args.provider)) {
      throw new GramCLIError(
        `Unknown --provider "${args.provider}". Supported: ${AI_PROVIDERS.join(", ")}.`,
        ExitCode.Error
      );
    }
    overrides.provider = args.provider;
  }
  if (args.model) overrides.model = args.model;
  return overrides;
}

// src/core/interactive.ts
function canPrompt() {
  return Boolean(process.stdin.isTTY && process.stdout.isTTY);
}

// src/ui/ai-model.ts
import chalk from "chalk";
import { log, select, text, isCancel } from "@clack/prompts";
function describeProvenance(selection) {
  if (selection.providerSource === "picker") return "picked interactively";
  const parts = [];
  if (selection.providerSource === "flag") parts.push("--provider");
  else if (selection.providerSource === "auto-detect")
    parts.push("provider auto-detected");
  if (selection.modelSource === "flag") parts.push("--model");
  else if (selection.modelSource === "default") parts.push("default model");
  return parts.length > 0 ? parts.join(", ") : null;
}
function renderAiSelection(selection, output) {
  const provenance = describeProvenance(selection);
  log.step(
    `${chalk.dim("model")} ${selection.provider} ${chalk.dim("\xB7")} ${chalk.bold(
      selection.model
    )}${provenance ? chalk.dim(` (${provenance})`) : ""}`,
    { output }
  );
}
async function pickAiModel(current) {
  const provider = await select({
    message: "Select an AI provider:",
    options: AI_PROVIDERS.map((value) => ({
      value,
      label: AI_PROVIDER_LABEL[value]
    })),
    initialValue: current?.provider
  });
  if (isCancel(provider)) return null;
  const recommended = RECOMMENDED_MODELS[provider];
  const inUse = current?.provider === provider && !recommended.includes(current.model) ? current.model : null;
  const picked = await select({
    message: "Select a model:",
    options: [
      ...inUse ? [{ value: inUse, label: `${inUse} (current)` }] : [],
      ...recommended.map((value, i) => ({
        value,
        label: i === 0 ? `${value} (Recommended)` : value
      })),
      { value: "other", label: "Other (Manual entry)" }
    ],
    initialValue: current?.provider === provider ? current.model : void 0
  });
  if (isCancel(picked)) return null;
  if (picked !== "other") return { provider, model: picked };
  const manual = await text({
    message: "Enter model name:",
    placeholder: RECOMMENDED_MODELS[provider][0]
  });
  if (isCancel(manual) || !manual) return null;
  return { provider, model: manual };
}
function fail(message, exitCode = ExitCode.Error) {
  log.error(message);
  process.exit(exitCode);
}
async function resolveAiForCommand(config, args, output, validate) {
  let overrides;
  try {
    overrides = parseAiOverrides(args);
  } catch (err) {
    if (err instanceof GramCLIError) fail(err.message, err.exitCode);
    throw err;
  }
  let selection;
  let resolveError;
  try {
    selection = resolveAiSelection(config, overrides);
  } catch (err) {
    if (!(err instanceof GramCLIError)) throw err;
    resolveError = err;
  }
  const wantsPicker = args["pick-model"] === true;
  if (wantsPicker && !canPrompt()) {
    fail(
      "--pick-model needs an interactive terminal. Pass --provider/--model instead."
    );
  }
  if (wantsPicker || !selection && canPrompt()) {
    if (!selection) log.warn("No AI provider configured yet.");
    const picked = await pickAiModel(selection);
    if (!picked) fail("Canceled \u2014 no model selected.", ExitCode.Ok);
    selection = {
      provider: picked.provider,
      model: picked.model,
      providerSource: "picker",
      modelSource: "picker"
    };
  }
  if (!selection) fail(resolveError?.message ?? "No AI provider configured.");
  renderAiSelection(selection, output);
  validate?.(selection);
  try {
    return { model: buildAiModel(selection, config), selection };
  } catch (err) {
    if (err instanceof GramCLIError) fail(err.message, err.exitCode);
    throw err;
  }
}

export {
  AI_ARGS,
  canPrompt,
  pickAiModel,
  resolveAiForCommand
};
